import{_ as o,c as l,a2 as a,o as i}from"./chunks/framework.CqbvlPrP.js";const d=JSON.parse('{"title":"第一千一百九十八章 弹指章 增支部1集51经到60经","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/1198第一千一百九十八章 弹指章 增支部1集51经到60经.md","filePath":"meditation/巴利文大藏经/1198第一千一百九十八章 弹指章 增支部1集51经到60经.md"}'),p={name:"meditation/巴利文大藏经/1198第一千一百九十八章 弹指章 增支部1集51经到60经.md"};function e(r,t,_,s,u,n){return i(),l("div",null,t[0]||(t[0]=[a('<h1 id="第一千一百九十八章-弹指章-增支部1集51经到60经" tabindex="-1">第一千一百九十八章 弹指章 增支部1集51经到60经 <a class="header-anchor" href="#第一千一百九十八章-弹指章-增支部1集51经到60经" aria-label="Permalink to &quot;第一千一百九十八章 弹指章 增支部1集51经到60经&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>增支部1集51经到60经</p><p>51经</p><ol start="51"><li>&quot;比丘们，此心本性光明。然而，它被外来的污染所污染。无闻凡夫不如实了知此事。因此，我说&#39;无闻凡夫没有心的修习&#39;。&quot;第一。</li></ol><p>52经</p><ol start="52"><li>&quot;比丘们，此心本性光明。而且，它已从外来的污染中解脱。多闻圣弟子如实了知此事。因此，我说&#39;多闻圣弟子有心的修习&#39;。&quot;第二。</li></ol><p>53经</p><ol start="53"><li>&quot;比丘们，即使比丘仅在弹指之间修习慈心，我说这样的比丘：&#39;他不空修禅那，遵行师教，依教奉行，不虚享用国人的供养&#39;。更何况那些多修习的人！&quot;第三。</li></ol><p>54经</p><ol start="54"><li>&quot;比丘们，即使比丘仅在弹指之间培育慈心，我说这样的比丘：&#39;他不空修禅那，遵行师教，依教奉行，不虚享用国人的供养&#39;。更何况那些多修习的人！&quot;第四。</li></ol><p>55经</p><ol start="55"><li>&quot;比丘们，即使比丘仅在弹指之间思惟慈心，我说这样的比丘：&#39;他不空修禅那，遵行师教，依教奉行，不虚享用国人的供养&#39;。更何况那些多修习的人！&quot;第五。</li></ol><p>56经</p><ol start="56"><li>&quot;比丘们，凡是不善法、属不善分、属不善类的，一切这些都以意为先导。意最先生起，然后不善法随之而生。&quot;第六。</li></ol><p>57经</p><ol start="57"><li>&quot;比丘们，凡是善法、属善分、属善类的，一切这些都以意为先导。意最先生起，然后善法随之而生。&quot;第七。</li></ol><p>58经</p><ol start="58"><li>&quot;比丘们，我不见有任何一法，能使未生的不善法生起，已生的善法衰退，如同放逸。比丘们，对于放逸者，未生的不善法生起，已生的善法衰退。&quot;第八。</li></ol><p>59经</p><ol start="59"><li>&quot;比丘们，我不见有任何一法，能使未生的善法生起，已生的不善法衰退，如同不放逸。比丘们，对于不放逸者，未生的善法生起，已生的不善法衰退。&quot;第九。</li></ol><p>60经</p><ol start="60"><li>&quot;比丘们，我不见有任何一法，能使未生的不善法生起，已生的善法衰退，如同懈怠。比丘们，对于懈怠者，未生的不善法生起，已生的善法衰退。&quot;第十。</li></ol><p>弹指章第六。</p>',24)]))}const c=o(p,[["render",e]]);export{d as __pageData,c as default};
